//! Forwards every dbghelp export to the real system DLL (stubs generated by build.rs).

use std::{os::windows::ffi::OsStrExt, path::PathBuf};

use windows_sys::Win32::System::{
    LibraryLoader::{GetProcAddress, LoadLibraryW},
    SystemInformation::GetSystemDirectoryW,
};

include!(concat!(env!("OUT_DIR"), "/exports.rs"));

/// Called from DllMain, before the server can call any forwarded export. `own` is this DLL.
/// Returns false when the real dbghelp could not be loaded, or the loader handed back this DLL
/// itself (possible under Wine, which may match the already loaded "dbghelp.dll" by name):
/// forwarding to ourselves would loop, so the table stays empty and the caller logs it.
pub fn init(own: *mut core::ffi::c_void) -> bool {
    let mut buffer = [0u16; 260];
    let len = unsafe { GetSystemDirectoryW(buffer.as_mut_ptr(), buffer.len() as u32) } as usize;
    let path = PathBuf::from(String::from_utf16_lossy(&buffer[..len])).join("dbghelp.dll");
    let wide: Vec<u16> = path.as_os_str().encode_wide().chain(Some(0)).collect();

    let real = unsafe { LoadLibraryW(wide.as_ptr()) };
    if real.is_null() || real == own {
        return false;
    }
    for (i, name) in NAMES.iter().enumerate() {
        let address = unsafe { GetProcAddress(real, name.as_ptr().cast()) };
        unsafe { DW_FWD_TABLE[i] = address.map_or(0, |f| f as usize) };
    }
    true
}
